#!/usr/bin/env perl
# ABOUTME: Test that app.pl generates IR by default (without --generate-ir flag)
# ABOUTME: Verifies issue #112 - IR generation should be standard behavior
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use lib 'lib';
use Test::More;
use File::Temp qw(tempfile);
use IPC::Run3;

# Test that app.pl generates IR by default (not just syntax check)
{
    # Create a simple test program
    my $test_program = q{
use 5.42.0;
my $x = 42;
};

    # Write test program to a temp file
    my ($fh, $filename) = tempfile(SUFFIX => '.pl', UNLINK => 1);
    print $fh $test_program;
    close $fh;

    # Run app.pl without any flags (default behavior)
    my @cmd = ($^X, 'app.pl', $filename);
    my ($stdout, $stderr);
    run3(\@cmd, \undef, \$stdout, \$stderr);
    my $exit_code = $? >> 8;

    # The parse should succeed
    is($exit_code, 0, 'app.pl exits successfully with simple program');
    like($stdout, qr/Parse successful/, 'app.pl reports parse success');

    # TODO: Currently this test will FAIL because app.pl doesn't generate IR by default
    # After implementing issue #112, we need to verify that IR was actually generated
    # This would require app.pl to expose the IR or provide a way to verify it was built
    # For now, we're testing that it at least parses successfully

    # The real test would be to check that:
    # 1. IR Builder was created
    # 2. Semantic semiring was used (not just Boolean)
    # 3. IR graph has nodes after parsing
    # But that requires modifying app.pl to expose this information
}

# Test that -c flag still does syntax-only checking (no IR generation)
{
    # Create a simple test program
    my $test_program = q{
use 5.42.0;
my $y = 100;
};

    # Write test program to a temp file
    my ($fh, $filename) = tempfile(SUFFIX => '.pl', UNLINK => 1);
    print $fh $test_program;
    close $fh;

    # Run app.pl with -c flag (syntax check mode)
    my @cmd = ($^X, 'app.pl', '-c', $filename);
    my ($stdout, $stderr);
    run3(\@cmd, \undef, \$stdout, \$stderr);
    my $exit_code = $? >> 8;

    # The syntax check should succeed
    is($exit_code, 0, 'app.pl -c exits successfully');
    like($stdout, qr/syntax OK/, 'app.pl -c reports syntax OK');
}

done_testing();

