if ($generate_ir_mode) {
    use Chalk::IR::Builder;
    use Chalk::IR::Optimizer::GVN;
    use Chalk::IR::Format::Dot;

    # Create IR Builder
    my $builder = Chalk::IR::Builder->new();

    # Create Semantic semiring with Builder in environment
    require Chalk::Semiring::Semantic;
    my $semiring = Chalk::Semiring::Semantic->new(
        grammar => $chalk_grammar,
        env => { ir_builder => $builder }
    );

    # Create parser
    my $parser = Chalk::Parser->new(
        grammar => $chalk_grammar,
        semiring => $semiring,
        preprocess => $preprocess
    );

    # Collect all input files
    my @files;
    if (@ARGV) {
        @files = @ARGV;
    } else {
        # Read file list from STDIN
        @files = <STDIN>;
        chomp(@files);
    }

    # Parse all files
    for my $file (@files) {
        next unless -f $file;

        # Read file
        open my $fh, '<', $file or do {
            warn("Cannot open $file: $!\n");
            next;
        };
        local $/;
        my $content = <$fh>;
        close $fh;

        # Parse
        my $result = $parser->parse_string($content);
        unless ($result) {
            warn("Failed to parse $file\n");
            next;
        }
    }

    # Get the IR graph
    my $graph = $builder->graph;

    # Run GVN optimization to deduplicate nodes
    my $gvn_result = Chalk::IR::Optimizer::GVN->run_gvn($graph);
    $graph = $gvn_result->{graph};
    my $metrics = $gvn_result->{metrics};

    # Output in requested format
    if ($output_format eq 'json') {
        # JSON output
        require JSON::PP;
        my $json = JSON::PP->new->utf8->pretty->canonical;

        my $nodes = $graph->nodes;
        my @node_list;
        for my $node_id (sort { $a <=> $b } keys %$nodes) {
            my $node = $nodes->{$node_id};
            push @node_list, {
                id => $node->id,
                op => $node->op,
                inputs => $node->inputs,
                data => $node->data,
            };
        }

        my $output = {
            entry => $graph->entry,
            nodes => \@node_list,
            metrics => {
                total_nodes => scalar(keys %$nodes),
                nodes_eliminated => $metrics->{nodes_eliminated},
            },
        };

        print($json->encode($output));
    } elsif ($output_format eq 'dot') {
        # GraphViz DOT output
        print(Chalk::IR::Format::Dot->format_graph($graph));
    } elsif ($output_format eq 'summary') {
        # Summary output (default)
        my $node_count = $graph->node_count;
        print("Generated IR with $node_count nodes\n");
        print("GVN eliminated $metrics->{nodes_eliminated} duplicate nodes\n");

        # Show node type distribution
        my $nodes = $graph->nodes;
        my %op_counts;
        for my $node (values %$nodes) {
            $op_counts{$node->op}++;
        }

        print("\nNode types:\n");
        for my $op (sort keys %op_counts) {
            print("  $op: $op_counts{$op}\n");
        }

        # Show entry point
        my $entry = $graph->entry;
        print("\nEntry node: $entry\n");
    } elsif ($output_format eq 'stats') {
        # Statistics output
        my $node_count = $graph->node_count;
        my $nodes = $graph->nodes;

        # Count node types
        my %op_counts;
        my %input_counts;
        for my $node (values %$nodes) {
            $op_counts{$node->op}++;
            my $num_inputs = scalar(@{$node->inputs});
            $input_counts{$num_inputs}++;
        }

        print("IR Statistics:\n");
        print("  Total nodes: $node_count\n");
        print("  Nodes eliminated by GVN: $metrics->{nodes_eliminated}\n");
        print("  Unique node types: " . scalar(keys %op_counts) . "\n");
        print("\nNode type distribution:\n");
        for my $op (sort { $op_counts{$b} <=> $op_counts{$a} } keys %op_counts) {
            my $count = $op_counts{$op};
            my $pct = sprintf("%.1f", 100 * $count / $node_count);
            print("  $op: $count ($pct%)\n");
        }

        print("\nInput count distribution:\n");
        for my $count (sort { $a <=> $b } keys %input_counts) {
            my $num = $input_counts{$count};
            my $pct = sprintf("%.1f", 100 * $num / $node_count);
            print("  $count inputs: $num nodes ($pct%)\n");
        }
    }

    exit 0;
}

